import {
  callService,
  createConnection,
  createLongLivedTokenAuth,
  subscribeEntities,
  type Connection,
  type HassEntities,
  type HassEntity,
  type HassServiceTarget,
} from 'home-assistant-js-websocket';
import { EventEmitter } from 'node:events';
import type { Action } from '../types/actions.js';

// ---------- Public types ----------

export interface EntityState {
  entity_id: string;
  state: string;
  attributes: Record<string, unknown>;
  last_changed: string;
  last_updated: string;
}

// Consumers augment this via the ambient file generated by `npm run codegen`.
// When empty (no codegen), HAState accepts any string. When populated, only
// known entity IDs are accepted and return types are narrowed per entity.
declare global {
  // eslint-disable-next-line @typescript-eslint/no-empty-interface
  interface HAEntities {}
}

type _HAStateKey = keyof HAEntities extends never ? string : keyof HAEntities;
export type HAState = <E extends _HAStateKey>(entity: E) =>
  (E extends keyof HAEntities ? EntityState & HAEntities[E] : EntityState) | undefined;

export interface HAContext {
  entitiesByLabel: (label: string) => string[];
  labelsFor: (entity: string) => string[];
  entitiesByArea: (area: string) => string[];
}

export interface StateChangedEvent {
  entity_id: string;
  old_state: EntityState | undefined;
  new_state: EntityState;
  correlation_id: string;
  parent_correlation_id?: string;
  root_correlation_id?: string;
  parent_automation_id?: string;
}

// Identifies the pipeline run that performed a write, so a resulting state_changed
// (bridged through HA) can be tagged with what caused it. See #28.
export interface WriteOrigin {
  correlationId: string;
  rootCorrelationId?: string;
  automationId: string;
}

const PENDING_WRITE_TTL_MS = 2000;

// Everything needed to both track a pending ack and, on timeout, publish a self-sufficient
// action_ack_timeout ObsEvent — kept separate from WriteOrigin/pendingWrites (correlation
// tagging) so the two concerns don't get conflated in implementation. See #55.
export interface AckOrigin {
  correlationId: string;
  rootCorrelationId?: string;
  automationId: string;
  location: string;
  subsystem: string;
  action: Action;
  // entity field/attribute name -> the value the dispatched call is expected to produce.
  expected: Record<string, unknown>;
}

export interface AckTimeoutEvent extends AckOrigin {
  entity_id: string;
}

// ---------- Internal types ----------

interface EntityRegistryEntry {
  entity_id: string;
  labels?: string[];
  area_id?: string | null;
  device_id?: string | null;
}

interface DeviceRegistryEntry {
  id: string;
  area_id?: string | null;
}

interface PendingAck extends AckOrigin {
  timer: NodeJS.Timeout;
}

function ackSatisfied(expected: Record<string, unknown>, state: EntityState): boolean {
  // HA represents every entity's state as a string, even numeric domains (number,
  // input_number, ...) — a dispatched call's data.value is typically a plain JS number, so
  // comparing `state` with strict equality never matches regardless of what HA does. See #158.
  return Object.entries(expected).every(([key, value]) =>
    key === 'state' ? String(state.state) === String(value) : state.attributes[key] === value,
  );
}

// ---------- Typed EventEmitter overloads ----------

export declare interface HAClient {
  on(event: 'state_changed', listener: (e: StateChangedEvent) => void): this;
  on(event: 'ready', listener: () => void): this;
  on(event: 'reconnected', listener: () => void): this;
  on(event: 'action_ack_timeout', listener: (e: AckTimeoutEvent) => void): this;
  emit(event: 'state_changed', e: StateChangedEvent): boolean;
  emit(event: 'ready'): boolean;
  emit(event: 'reconnected'): boolean;
  emit(event: 'action_ack_timeout', e: AckTimeoutEvent): boolean;
}

// Quiet period after the last registry-change signal before a reload starts.
// Long enough to swallow a bulk edit's burst, short enough that label/area
// changes still feel live.
const REGISTRY_RELOAD_DEBOUNCE_MS = 500;

export class HAClient extends EventEmitter {
  private readonly stateCache = new Map<string, EntityState>();
  // Not readonly: loadEntityRegistry builds fresh maps and swaps the references
  // in one synchronous step, so readers never see a half-built registry.
  private labelToEntities = new Map<string, Set<string>>();
  private entityToLabels = new Map<string, string[]>();
  private areaToEntities = new Map<string, Set<string>>();

  // entity_id -> origin of the write that's expected to produce a state_changed for it.
  // Self-evicts after PENDING_WRITE_TTL_MS; consumed (deleted) the moment it's matched.
  private readonly pendingWrites = new Map<string, WriteOrigin>();

  // entity_id -> ack tracking for a dispatched call awaiting its expected state/attribute
  // change. Consumed (timer cleared, deleted) the moment diffAndUpdate sees a satisfying
  // state_changed; otherwise self-fires action_ack_timeout after its own timeout.
  private readonly pendingAcks = new Map<string, PendingAck>();

  private connection: Connection | null = null;

  // True between a disconnect event and the next subscribeEntities callback.
  // During this window we repopulate silently — no state_changed events emitted.
  private reconnecting = false;

  // Registry reloads are coalesced in two layers (see #199). A trailing debounce
  // collapses a burst of entity_registry_updated events (HA can fire many in a
  // row for a single bulk edit) into one reload start. Single-flight then caps
  // concurrency at one in-flight loadEntityRegistry() plus at most one trailing
  // rerun. Single-flight alone is not enough: a burst longer than one fetch
  // would still cause back-to-back full reloads, each a full
  // config/entity_registry/list fetch.
  private registryReloadTimer: ReturnType<typeof setTimeout> | null = null;
  private registryReloadInFlight: Promise<void> | null = null;
  private registryReloadPending = false;

  private _readyResolve!: () => void;
  readonly ready: Promise<void> = new Promise((resolve) => {
    this._readyResolve = resolve;
  });

  // Synchronous accessors passed into context builders.
  readonly state: HAState = ((entity: string) => this.stateCache.get(entity)) as HAState;

  readonly context: HAContext = {
    entitiesByLabel: (label) => Array.from(this.labelToEntities.get(label) ?? []),
    labelsFor: (entity) => this.entityToLabels.get(entity) ?? [],
    entitiesByArea: (area) => Array.from(this.areaToEntities.get(area) ?? []),
  };

  get entityCount(): number {
    return this.stateCache.size;
  }

  get registryStats(): { labels: number; areas: number } {
    return { labels: this.labelToEntities.size, areas: this.areaToEntities.size };
  }

  async callService(
    domain: string,
    service: string,
    target?: HassServiceTarget,
    data?: Record<string, unknown>,
    origin?: WriteOrigin,
  ): Promise<void> {
    if (!this.connection) throw new Error('HAClient not connected');
    const entityId = (target as { entity_id?: string } | undefined)?.entity_id;
    if (origin && entityId) this.registerPendingWrite(entityId, origin);
    await callService(this.connection, domain, service, data, target);
  }

  // Registers that `origin` is expected to produce a state_changed for `entityId` — consumed
  // (and stamped as parent_correlation_id/parent_automation_id) by diffAndUpdate on match, or
  // self-evicted after PENDING_WRITE_TTL_MS if nothing arrives. Used by ha.call_service writes
  // (automatically, via target.entity_id) and by mqtt.publish writes that declare `impliesEntity`
  // (explicitly, since a topic alone carries no entity information — see #28, #138).
  registerPendingWrite(entityId: string, origin: WriteOrigin): void {
    this.pendingWrites.set(entityId, origin);
    setTimeout(() => this.pendingWrites.delete(entityId), PENDING_WRITE_TTL_MS);
  }

  // Registers that `entityId` is expected to reach `origin.expected` (a field/attribute ->
  // value map) within `timeoutMs`. Consumed (timer cleared, deleted) by diffAndUpdate the
  // moment a satisfying state_changed arrives; otherwise emits action_ack_timeout on expiry
  // with the same origin, so a listener has everything needed to publish a self-sufficient
  // ObsEvent without HAClient itself knowing about observability. See #55.
  registerPendingAck(entityId: string, origin: AckOrigin, timeoutMs: number): void {
    const timer = setTimeout(() => {
      this.pendingAcks.delete(entityId);
      this.emit('action_ack_timeout', { ...origin, entity_id: entityId });
    }, timeoutMs);
    this.pendingAcks.set(entityId, { ...origin, timer });
  }

  disconnect(): void {
    // Cancel before closing so no reload fires against a torn-down connection.
    if (this.registryReloadTimer) {
      clearTimeout(this.registryReloadTimer);
      this.registryReloadTimer = null;
    }
    this.registryReloadPending = false;
    this.connection?.close();
    this.connection = null;
  }

  async connect(url: string, token: string): Promise<void> {
    const auth = createLongLivedTokenAuth(url, token);
    this.connection = await createConnection({ auth });

    // Reload registry and repopulate cache silently on reconnect.
    this.connection.addEventListener('disconnected', () => {
      this.reconnecting = true;
    });

    await this.loadEntityRegistry();

    this.connection.subscribeEvents(() => {
      console.log('[ha-client] entity_registry_updated received — reloading registry');
      this.requestRegistryReload();
    }, 'entity_registry_updated').catch((err) => {
      console.error('[ha-client] failed to subscribe to entity_registry_updated:', err);
    });

    // Device area changes alter inherited entity areas; same coalesced reload path.
    this.connection.subscribeEvents(() => {
      console.log('[ha-client] device_registry_updated received — reloading registry');
      this.requestRegistryReload();
    }, 'device_registry_updated').catch((err) => {
      console.error('[ha-client] failed to subscribe to device_registry_updated:', err);
    });

    let firstSnapshot = true;

    subscribeEntities(this.connection, (entities: HassEntities) => {
      if (firstSnapshot) {
        firstSnapshot = false;
        this.repopulateCache(entities);
        this._readyResolve();
        this.emit('ready');
      } else if (this.reconnecting) {
        this.reconnecting = false;
        // Reload registry in the background — don't block the cache repopulate.
        this.requestRegistryReload();
        this.repopulateCache(entities);
        this.emit('reconnected');
      } else {
        this.diffAndUpdate(entities);
      }
    });
  }

  // ---------- Private ----------

  private repopulateCache(entities: HassEntities): void {
    this.stateCache.clear();
    for (const [id, entity] of Object.entries(entities)) {
      this.stateCache.set(id, toEntityState(id, entity));
    }
  }

  private diffAndUpdate(entities: HassEntities): void {
    for (const [id, rawEntity] of Object.entries(entities)) {
      const old_state = this.stateCache.get(id);
      const new_state = toEntityState(id, rawEntity);

      // last_updated changes whenever state or attributes change in HA. It's also compared as
      // a millisecond-precision string (see toEntityState), so two distinct state changes to
      // the same entity within the same millisecond collide on last_updated alone — compare
      // state directly too so a genuine transition is never silently dropped. See #170.
      if (!old_state || old_state.state !== new_state.state || old_state.last_updated !== new_state.last_updated) {
        this.stateCache.set(id, new_state);

        const ack = this.pendingAcks.get(id);
        if (ack && ackSatisfied(ack.expected, new_state)) {
          clearTimeout(ack.timer);
          this.pendingAcks.delete(id);
        }

        const correlation_id = crypto.randomUUID();
        const origin = this.pendingWrites.get(id);
        if (origin) this.pendingWrites.delete(id);
        this.emit('state_changed', {
          entity_id: id,
          old_state,
          new_state,
          correlation_id,
          root_correlation_id: origin ? (origin.rootCorrelationId ?? origin.correlationId) : correlation_id,
          ...(origin && { parent_correlation_id: origin.correlationId, parent_automation_id: origin.automationId }),
        });
      }
    }

    // Prune entities that disappeared from the snapshot.
    for (const id of this.stateCache.keys()) {
      if (!(id in entities)) {
        this.stateCache.delete(id);
      }
    }
  }

  // Debounced entry point for registry reloads — see registryReloadTimer field
  // comment. Each call re-arms the timer so only the last signal in a burst
  // starts a reload. The connect-time load deliberately bypasses this: `ready`
  // must not wait on a debounce.
  private requestRegistryReload(): void {
    if (this.registryReloadTimer) clearTimeout(this.registryReloadTimer);
    this.registryReloadTimer = setTimeout(() => {
      this.registryReloadTimer = null;
      this.startRegistryReload();
    }, REGISTRY_RELOAD_DEBOUNCE_MS);
  }

  // Single-flight: at most one loadEntityRegistry in flight, with any requests
  // that arrive meanwhile collapsed into one trailing rerun so the final state
  // is never dropped. Never throws; failures are logged and swallowed so a
  // connection hiccup can't surface as an unhandled rejection.
  private startRegistryReload(): void {
    if (this.registryReloadInFlight) {
      this.registryReloadPending = true;
      return;
    }

    this.registryReloadInFlight = (async () => {
      do {
        this.registryReloadPending = false;
        try {
          await this.loadEntityRegistry();
          console.log(`[ha-client] registry reloaded (${this.labelToEntities.size} labels, ${this.areaToEntities.size} areas)`);
        } catch (err) {
          console.error('[ha-client] registry reload failed:', err);
        }
      } while (this.registryReloadPending);
      this.registryReloadInFlight = null;
    })();
  }

  private async loadEntityRegistry(): Promise<void> {
    if (!this.connection) return;

    // Fetched together so the entity and device views come from one moment.
    const [entries, devices] = (await Promise.all([
      this.connection.sendMessagePromise({ type: 'config/entity_registry/list' }),
      this.connection.sendMessagePromise({ type: 'config/device_registry/list' }),
    ])) as [EntityRegistryEntry[], DeviceRegistryEntry[]];
    if (!Array.isArray(entries)) {
      throw new Error('config/entity_registry/list returned a non-array payload');
    }
    if (!Array.isArray(devices)) {
      throw new Error('config/device_registry/list returned a non-array payload');
    }

    // Entities without their own area inherit their device's area (as HA does).
    const deviceToArea = new Map<string, string>();
    for (const device of devices) {
      if (device.area_id) deviceToArea.set(device.id, device.area_id);
    }

    // Build into locals and swap only once complete: a failed fetch (thrown
    // above) or a malformed entry (thrown below) leaves the previous maps intact.
    const labelToEntities = new Map<string, Set<string>>();
    const entityToLabels = new Map<string, string[]>();
    const areaToEntities = new Map<string, Set<string>>();

    for (const entry of entries) {
      const labels = entry.labels ?? [];
      entityToLabels.set(entry.entity_id, labels);
      for (const label of labels) {
        let set = labelToEntities.get(label);
        if (!set) {
          set = new Set();
          labelToEntities.set(label, set);
        }
        set.add(entry.entity_id);
      }

      // `||` not `??`: an empty-string area_id means "unset" and must fall back.
      const area = entry.area_id || (entry.device_id ? deviceToArea.get(entry.device_id) : undefined);
      if (area) {
        let set = areaToEntities.get(area);
        if (!set) {
          set = new Set();
          areaToEntities.set(area, set);
        }
        set.add(entry.entity_id);
      }
    }

    this.labelToEntities = labelToEntities;
    this.entityToLabels = entityToLabels;
    this.areaToEntities = areaToEntities;
  }
}

// ---------- Helpers ----------

function toEntityState(entity_id: string, entity: HassEntity): EntityState {
  return {
    entity_id,
    state: entity.state,
    attributes: entity.attributes as Record<string, unknown>,
    last_changed: entity.last_changed,
    last_updated: entity.last_updated,
  };
}
